record.field:
Company information {company_information}
Department {department}
quest_instructions {quest_instructions}
quest_list {quest_list}
department job_list   {job_list}
odoo_modules {module_list}

for department in records:
    result = quest.build(session=session,record=department).invoke({})
    if result:
        answer = quest.get_last_ai_message_content(result)
        department.write({'goals_responsibilities':quest.markdown2html(answer)})

objects=[]
for department in records:
    result = agents[0].prompt_agent(session=session,debug=quest.debug,department=f"{department.name=} {department.goals_responsibilities=}",
                                    company_information=f"{company_id.name=} {company_id.company_mission=} {company_id.company_values=}",
                                    quest_instructions=f"{quest.description} ",
                                    #quest_list=quest._get_quest_list_department(department),
                                    quest_list='',
                                    job_list=quest._get_jobs(department),
                                    module_list=module_list,
                                    )
    if quest.debug:
        _logger.warning(f"{quest.json2dict(result.content)=}")
    for  ai_staff in quest.json2dict(result.content):
        if quest.debug:
            _logger.warning(f"Quest to create {ai_staff=}")
        objects.append(self.env['ai.quest'].create({
                    'name': ai_staff['name'],
                    'description': f"{ai_staff['description']}",
                    'init_type': ai_staff['init_type'],
                    'department_id': department.id,
                    'ai_type': 'ai-staff',
                }))
